# Pengo Nyx - offline achievement screenshot reader (v1)
#
# Reads only screenshots selected with -InputPath. Windows.Media.Ocr runs on
# this PC. The helper does not contact a server or interact with a game.
# Only exact, unique English achievement names with nearby completion evidence
# are exported. Uncertain rows are skipped.

[CmdletBinding()]
param(
  [Parameter(Mandatory = $true)]
  [ValidateSet('gi', 'hsr')]
  [string]$Game,

  [string]$InputPath = '',
  [string]$OutputPath = '',
  [switch]$Force,
  [switch]$DryRun
)

Set-StrictMode -Version 2.0
$ErrorActionPreference = 'Stop'
try { [Console]::OutputEncoding = [System.Text.Encoding]::UTF8 } catch {}

$MaxImages = 250
$MaxImageBytes = 30MB
$MaxTotalBytes = 500MB
$MaxPixels = 50000000
$ConfiguredMaxDimension = 10000
$SupportedExtensions = @('.png', '.jpg', '.jpeg')
$ReleaseDates = @{
  gi = [DateTime]::new(2020, 9, 28)
  hsr = [DateTime]::new(2023, 4, 26)
}
$script:CloudWarningShown = $false
$CrossGameDuplicateNames = @{
  'dance! dance! dance!' = $true
  'electric dreams' = $true
  'non-stop' = $true
  'fight fire with fire' = $true
  'the long goodbye' = $true
  'swordseeker' = $true
  'moonless night' = $true
}

# Generated from the pinned released catalogs in Database/Achievements.
# It contains only normalized names that map to exactly one released ID.
$CatalogGzipBase64 = @'

'@

function Normalize-Name {
  param([AllowEmptyString()][string]$Value)
  if ($null -eq $Value) { return '' }
  $value = $Value.Normalize([System.Text.NormalizationForm]::FormKC)
  $value = $value.Replace([char]0x2018, "'").Replace([char]0x2019, "'")
  $value = $value.Replace([char]0x201C, '"').Replace([char]0x201D, '"')
  $value = $value.Replace([char]0x2013, '-').Replace([char]0x2014, '-')
  return ([regex]::Replace($value, '\s+', ' ').Trim().ToLowerInvariant())
}

function Read-EmbeddedCatalog {
  $compressed = [Convert]::FromBase64String(($CatalogGzipBase64 -replace '\s', ''))
  $input = New-Object System.IO.MemoryStream(, $compressed)
  $gzip = New-Object System.IO.Compression.GZipStream($input, [System.IO.Compression.CompressionMode]::Decompress)
  $reader = New-Object System.IO.StreamReader($gzip, [System.Text.Encoding]::UTF8)
  try { return ($reader.ReadToEnd() | ConvertFrom-Json) }
  finally { $reader.Dispose(); $gzip.Dispose(); $input.Dispose() }
}

function Get-GameCatalog {
  param([object]$Catalog, [string]$SelectedGame)
  $table = @{}
  foreach ($property in $Catalog.$SelectedGame.PSObject.Properties) {
    $id = [string]$property.Value
    if ($id -notmatch '^\d+$') { throw 'The embedded catalog is invalid.' }
    if ($CrossGameDuplicateNames.ContainsKey([string]$property.Name)) { continue }
    $table[[string]$property.Name] = $id
  }
  if ($table.Count -lt 1000) { throw 'The embedded catalog is incomplete.' }
  return $table
}

function Test-ReparsePoint {
  param([System.IO.FileSystemInfo]$Item)
  return (($Item.Attributes -band [System.IO.FileAttributes]::ReparsePoint) -ne 0)
}

function Assert-LocalPath {
  param([string]$Path)
  if ($Path -match '^(?:\\\\|//|\\\\[?.]\\)') { throw 'Only plain local paths are accepted.' }
  $root = [System.IO.Path]::GetPathRoot($Path)
  if (-not $root -or $root -match '^(?:\\\\|//)') { throw 'Only plain local paths are accepted.' }
  $drive = New-Object System.IO.DriveInfo($root)
  if ($drive.DriveType -eq [System.IO.DriveType]::Network -or
      $drive.DriveType -eq [System.IO.DriveType]::Unknown -or
      $drive.DriveType -eq [System.IO.DriveType]::NoRootDirectory) {
    throw 'Only plain local paths are accepted.'
  }
}

function Warn-CloudSyncedPath {
  param([string]$Path)
  if ($script:CloudWarningShown) { return }
  $candidates = @($env:OneDrive, $env:OneDriveConsumer, $env:OneDriveCommercial) | Where-Object { $_ }
  $looksSynced = $Path -match '(?i)\\(?:OneDrive|Dropbox|Google Drive|iCloudDrive)(?:\\|$)'
  foreach ($candidate in $candidates) {
    $root = [System.IO.Path]::GetFullPath($candidate).TrimEnd('\') + '\'
    if ($Path.StartsWith($root, [StringComparison]::OrdinalIgnoreCase)) { $looksSynced = $true }
  }
  if ($looksSynced) {
    Write-Host 'Privacy warning: the selected location may be cloud-synced. Use a plain local folder if you do not want screenshots or JSON copied by another app.' -ForegroundColor Yellow
    $script:CloudWarningShown = $true
  }
}

function Assert-NoReparseChain {
  param([string]$Path)
  $current = Get-Item -LiteralPath $Path -Force
  while ($null -ne $current) {
    if (Test-ReparsePoint $current) { throw "Reparse points are not accepted: $($current.FullName)" }
    if ($current -is [System.IO.FileInfo]) { $current = $current.Directory }
    elseif ($current -is [System.IO.DirectoryInfo]) { $current = $current.Parent }
    else { $current = $null }
  }
}

function Assert-PlainPath {
  param([string]$Path, [switch]$MustExist)
  $full = [System.IO.Path]::GetFullPath($Path)
  Assert-LocalPath $full
  if ($MustExist -and -not (Test-Path -LiteralPath $full)) { throw "Path not found: $full" }
  if (Test-Path -LiteralPath $full) {
    Assert-NoReparseChain $full
  }
  Warn-CloudSyncedPath $full
  return $full
}

function Get-ImageFiles {
  param([string]$SelectedPath)
  if (-not $SelectedPath) { throw 'Choose a screenshot file or folder with -InputPath.' }
  $full = Assert-PlainPath -Path $SelectedPath -MustExist
  $item = Get-Item -LiteralPath $full -Force
  if ($item.PSIsContainer) {
    $files = @(Get-ChildItem -LiteralPath $full -File -Force | Where-Object {
      $SupportedExtensions -contains $_.Extension.ToLowerInvariant()
    } | Sort-Object FullName)
  } else {
    if ($SupportedExtensions -notcontains $item.Extension.ToLowerInvariant()) {
      throw 'Only PNG and JPEG screenshots are accepted.'
    }
    $files = @($item)
  }
  if ($files.Count -eq 0) { throw 'No PNG or JPEG screenshots were found.' }
  if ($files.Count -gt $MaxImages) { throw "Too many screenshots. The limit is $MaxImages." }
  [long]$total = 0
  foreach ($file in $files) {
    if (Test-ReparsePoint $file) { throw "Reparse points are not accepted: $($file.FullName)" }
    if ($file.Length -le 0 -or $file.Length -gt $MaxImageBytes) { throw "Screenshot size is outside the safe limit: $($file.Name)" }
    $total += $file.Length
  }
  if ($total -gt $MaxTotalBytes) { throw 'The selected screenshots are too large in total.' }
  return $files
}

function Await-WinRt {
  param([object]$Operation, [Type]$ResultType)
  $method = [System.WindowsRuntimeSystemExtensions].GetMethods() | Where-Object {
    $_.Name -eq 'AsTask' -and $_.IsGenericMethod -and $_.GetParameters().Count -eq 1
  } | Select-Object -First 1
  if (-not $method) { throw 'Windows Runtime support is unavailable.' }
  $task = $method.MakeGenericMethod($ResultType).Invoke($null, @($Operation))
  $task.GetAwaiter().GetResult()
}

function Get-OcrLines {
  param([string]$Path, [object]$Engine, [int]$MaxAllowedDimension)
  $storageFileType = [Windows.Storage.StorageFile, Windows.Storage, ContentType = WindowsRuntime]
  $fileAccessModeType = [Windows.Storage.FileAccessMode, Windows.Storage, ContentType = WindowsRuntime]
  $streamType = [Windows.Storage.Streams.IRandomAccessStream, Windows.Storage.Streams, ContentType = WindowsRuntime]
  $decoderType = [Windows.Graphics.Imaging.BitmapDecoder, Windows.Graphics.Imaging, ContentType = WindowsRuntime]
  $bitmapType = [Windows.Graphics.Imaging.SoftwareBitmap, Windows.Graphics.Imaging, ContentType = WindowsRuntime]
  $resultType = [Windows.Media.Ocr.OcrResult, Windows.Foundation, ContentType = WindowsRuntime]

  $file = Await-WinRt ($storageFileType::GetFileFromPathAsync($Path)) $storageFileType
  $readMode = [Enum]::Parse($fileAccessModeType, 'Read')
  $stream = Await-WinRt ($file.OpenAsync($readMode)) $streamType
  try {
    $decoder = Await-WinRt ($decoderType::CreateAsync($stream)) $decoderType
    [long]$pixels = [long]$decoder.PixelWidth * [long]$decoder.PixelHeight
    if ($decoder.PixelWidth -gt $MaxAllowedDimension -or $decoder.PixelHeight -gt $MaxAllowedDimension -or $pixels -gt $MaxPixels) {
      throw 'A screenshot exceeds the safe pixel limits.'
    }
    $bitmap = Await-WinRt ($decoder.GetSoftwareBitmapAsync()) $bitmapType
    try {
      $result = Await-WinRt ($Engine.RecognizeAsync($bitmap)) $resultType
      $lines = @()
      foreach ($line in $result.Lines) {
        $words = @($line.Words)
        if ($words.Count -eq 0) { continue }
        $left = ($words | ForEach-Object { $_.BoundingRect.X } | Measure-Object -Minimum).Minimum
        $top = ($words | ForEach-Object { $_.BoundingRect.Y } | Measure-Object -Minimum).Minimum
        $right = ($words | ForEach-Object { $_.BoundingRect.X + $_.BoundingRect.Width } | Measure-Object -Maximum).Maximum
        $bottom = ($words | ForEach-Object { $_.BoundingRect.Y + $_.BoundingRect.Height } | Measure-Object -Maximum).Maximum
        $lines += [pscustomobject]@{ Text = [string]$line.Text; Left = $left; Top = $top; Right = $right; Bottom = $bottom }
      }
      return @($lines | Sort-Object Top, Left)
    } finally { if ($bitmap -is [IDisposable]) { $bitmap.Dispose() } }
  } finally { if ($stream -is [IDisposable]) { $stream.Dispose() } }
}

function Get-CompletionDate {
  param([string]$Text, [DateTime]$MinimumDate, [DateTime]$MaximumDate)
  $normalized = Normalize-Name $Text
  if ($normalized -match '\b(?:not|never|incomplete|locked|pending|progress|uncertain|unknown|yet|unobtained|unachieved)\b') { return $null }
  $match = [regex]::Match($normalized, '^(?:(?:completed|obtained|achieved|unlocked)(?:\s+(?:on|at))?\s+)?(20\d{2})[./-](\d{1,2})[./-](\d{1,2})$')
  if (-not $match.Success) { return $null }
  try { $date = [DateTime]::new([int]$match.Groups[1].Value, [int]$match.Groups[2].Value, [int]$match.Groups[3].Value) }
  catch { return $null }
  if ($date -lt $MinimumDate.Date -or $date -gt $MaximumDate.Date) { return $null }
  return $date
}

function Remove-CompletionDate {
  param([string]$Text)
  $value = [regex]::Replace($Text, '(?i)\s+(?:(?:completed|obtained|achieved|unlocked)(?:\s+(?:on|at))?\s+)?20\d{2}[./-]\d{1,2}[./-]\d{1,2}\s*$', '')
  return $value.Trim(' ', "`t", '|', '-', ':')
}

function Get-AxisGap {
  param([double]$FirstStart, [double]$FirstEnd, [double]$SecondStart, [double]$SecondEnd)
  if ($FirstEnd -lt $SecondStart) { return ($SecondStart - $FirstEnd) }
  if ($SecondEnd -lt $FirstStart) { return ($FirstStart - $SecondEnd) }
  return 0
}

function Test-SameCardGeometry {
  param([object]$Title, [object]$Evidence)
  $titleHeight = [Math]::Max(1, $Title.Bottom - $Title.Top)
  $verticalGap = Get-AxisGap $Title.Top $Title.Bottom $Evidence.Top $Evidence.Bottom
  $horizontalGap = Get-AxisGap $Title.Left $Title.Right $Evidence.Left $Evidence.Right
  $maxVerticalGap = [Math]::Max(80, $titleHeight * 2.5)
  return ($verticalGap -le $maxVerticalGap -and $horizontalGap -le 20)
}

function Test-WrappedTitleGeometry {
  param([object]$First, [object]$Second)
  $firstHeight = [Math]::Max(1, $First.Bottom - $First.Top)
  $verticalStep = $Second.Top - $First.Top
  $horizontalGap = Get-AxisGap $First.Left $First.Right $Second.Left $Second.Right
  return ($verticalStep -ge ($firstHeight * 0.5) -and $verticalStep -le ($firstHeight + 45) -and $horizontalGap -le 20)
}

function Match-OcrLines {
  param([object[]]$Lines, [hashtable]$Catalog, [DateTime]$MinimumDate, [DateTime]$MaximumDate)
  $matched = New-Object System.Collections.Generic.HashSet[string]
  $titleCandidates = @()
  for ($i = 0; $i -lt $Lines.Count; $i++) {
    $windows = @([pscustomobject]@{ Text = $Lines[$i].Text; Left = $Lines[$i].Left; Top = $Lines[$i].Top; Right = $Lines[$i].Right; Bottom = $Lines[$i].Bottom })
    if ($i + 1 -lt $Lines.Count -and (Test-WrappedTitleGeometry $Lines[$i] $Lines[$i + 1])) {
      $windows += [pscustomobject]@{
        Text = "$($Lines[$i].Text) $($Lines[$i + 1].Text)"
        Left = [Math]::Min($Lines[$i].Left, $Lines[$i + 1].Left)
        Top = [Math]::Min($Lines[$i].Top, $Lines[$i + 1].Top)
        Right = [Math]::Max($Lines[$i].Right, $Lines[$i + 1].Right)
        Bottom = [Math]::Max($Lines[$i].Bottom, $Lines[$i + 1].Bottom)
      }
    }
    foreach ($window in $windows) {
      $title = Normalize-Name (Remove-CompletionDate $window.Text)
      if (-not $Catalog.ContainsKey($title)) { continue }
      $titleCandidates += [pscustomobject]@{
        Id = $Catalog[$title]
        Window = $window
        Key = "{0}:{1}:{2}:{3}:{4}" -f $Catalog[$title], $window.Left, $window.Top, $window.Right, $window.Bottom
      }
    }
  }

  $assignedTitles = New-Object System.Collections.Generic.HashSet[string]
  $dateLines = @($Lines | Where-Object { $null -ne (Get-CompletionDate $_.Text $MinimumDate $MaximumDate) })
  foreach ($evidence in $dateLines) {
    $compatible = @()
    foreach ($candidate in $titleCandidates) {
      if ($candidate.Window.Top -gt $evidence.Top -or -not (Test-SameCardGeometry $candidate.Window $evidence)) { continue }
      $verticalGap = Get-AxisGap $candidate.Window.Top $candidate.Window.Bottom $evidence.Top $evidence.Bottom
      $compatible += [pscustomobject]@{ Candidate = $candidate; Distance = [double]$verticalGap }
    }
    if ($compatible.Count -eq 0) { continue }
    $nearestDistance = ($compatible | Measure-Object -Property Distance -Minimum).Minimum
    $nearest = @($compatible | Where-Object { $_.Distance -eq $nearestDistance })
    $nearestIds = @($nearest | ForEach-Object { $_.Candidate.Id } | Sort-Object -Unique)
    if ($nearestIds.Count -ne 1) { continue }
    $winner = @($nearest | Where-Object { $_.Candidate.Id -eq $nearestIds[0] } | Sort-Object { $_.Candidate.Window.Top } -Descending)[0].Candidate
    [void]$matched.Add($winner.Id)
    [void]$assignedTitles.Add($winner.Key)
  }

  $skipped = [Math]::Max(0, $titleCandidates.Count - $assignedTitles.Count)
  return [pscustomobject]@{ Ids = @($matched); Reviewed = $titleCandidates.Count; Skipped = $skipped }
}

function Resolve-OutputPath {
  param([string]$RequestedPath)
  if (-not $RequestedPath) {
    $RequestedPath = Join-Path (Get-Location) ("pengo-achievements-{0}-{1}.json" -f $Game, (Get-Date -Format 'yyyyMMdd-HHmmss'))
  }
  $full = [System.IO.Path]::GetFullPath($RequestedPath)
  Assert-LocalPath $full
  if ([System.IO.Path]::GetExtension($full).ToLowerInvariant() -ne '.json') { throw 'OutputPath must end in .json.' }
  $parent = Split-Path -Parent $full
  if (-not $parent -or -not (Test-Path -LiteralPath $parent -PathType Container)) { throw 'The output folder does not exist.' }
  $parentItem = Get-Item -LiteralPath $parent -Force
  Assert-NoReparseChain $parentItem.FullName
  Warn-CloudSyncedPath $full
  if ((Test-Path -LiteralPath $full) -and -not $Force) { throw 'The output file already exists. Use -Force to replace it.' }
  if (Test-Path -LiteralPath $full) {
    $existing = Get-Item -LiteralPath $full -Force
    if ($existing.PSIsContainer -or (Test-ReparsePoint $existing)) { throw 'The output path is not a plain file.' }
  }
  return $full
}

function Write-AtomicJson {
  param([string]$Path, [string[]]$Ids)
  $key = if ($Game -eq 'gi') { 'gi_achievements' } else { 'hsr_achievements' }
  $json = '{"' + $key + '":[' + (($Ids | ForEach-Object { [string]([long]$_) }) -join ',') + "]}`n"
  $temp = Join-Path (Split-Path -Parent $Path) ('.' + [System.IO.Path]::GetFileName($Path) + '.' + [Guid]::NewGuid().ToString('N') + '.tmp')
  $backup = $temp + '.bak'
  try {
    [System.IO.File]::WriteAllText($temp, $json, (New-Object System.Text.UTF8Encoding($false)))
    if (Test-Path -LiteralPath $Path) { [System.IO.File]::Replace($temp, $Path, $backup) }
    else { [System.IO.File]::Move($temp, $Path) }
  } finally {
    if (Test-Path -LiteralPath $temp) { Remove-Item -LiteralPath $temp -Force }
    if (Test-Path -LiteralPath $backup) { Remove-Item -LiteralPath $backup -Force }
  }
}

try {
  Write-Host 'Pengo Nyx - offline achievement screenshot reader' -ForegroundColor Cyan
  $catalog = Get-GameCatalog (Read-EmbeddedCatalog) $Game
  $files = @(Get-ImageFiles $InputPath)
  Add-Type -AssemblyName System.Runtime.WindowsRuntime
  $languageType = [Windows.Globalization.Language, Windows.Globalization, ContentType = WindowsRuntime]
  $language = [Activator]::CreateInstance($languageType, @('en-US'))
  $engineType = [Windows.Media.Ocr.OcrEngine, Windows.Foundation, ContentType = WindowsRuntime]
  $engine = $engineType::TryCreateFromLanguage($language)
  if (-not $engine) { throw 'Windows English offline OCR is not installed.' }
  $engineDimension = [int]$engineType::MaxImageDimension
  $maxAllowedDimension = [Math]::Min($ConfiguredMaxDimension, $engineDimension)
  if ($maxAllowedDimension -le 0) { throw 'Windows offline OCR reported an invalid image limit.' }
  $ids = New-Object System.Collections.Generic.HashSet[string]
  $reviewed = 0
  $skipped = 0
  foreach ($file in $files) {
    $ocrLines = @(Get-OcrLines -Path $file.FullName -Engine $engine -MaxAllowedDimension $maxAllowedDimension)
    $result = Match-OcrLines $ocrLines $catalog $ReleaseDates[$Game] ([DateTime]::Today)
    foreach ($id in @($result.Ids)) { [void]$ids.Add($id) }
    $reviewed += $result.Reviewed
    $skipped += $result.Skipped
  }
  $summary = [pscustomobject]@{ Ids = @($ids); Reviewed = $reviewed; Skipped = $skipped; Files = $files.Count }

  $sortedIds = @($summary.Ids | Sort-Object { [long]$_ } -Unique)
  if ($sortedIds.Count -eq 0) { throw 'No certain completed achievements were found. No output was written.' }
  if ($sortedIds.Count -gt $catalog.Count) { throw 'The result exceeds the released catalog.' }

  Write-Host ("Checked {0} file(s); found {1} certain completed achievement(s); skipped {2} uncertain candidate(s)." -f $summary.Files, $sortedIds.Count, $summary.Skipped)
  if ($DryRun) {
    Write-Host 'Dry run: no file was written.' -ForegroundColor Yellow
  } else {
    $destination = Resolve-OutputPath $OutputPath
    Write-AtomicJson -Path $destination -Ids $sortedIds
    Write-Host 'Saved the local JSON file.' -ForegroundColor Green
    Write-Host 'Choose this JSON file in the Nyx achievement ledger to preview it.'
  }
} catch {
  [Console]::Error.WriteLine('The extractor stopped safely. No output was written. Check that the selected files are plain local English PNG/JPEG screenshots with a visible completion date.')
  exit 1
}
